143			check func(any) bool
144			label string
145		}{
146			{isNumber("9007199254740993"), "number 9007199254740993"},
147			{isString("9007199254740993"), "string \"9007199254740993\""},
148			{isNumber("1.0000000000000000001"), "number 1.0000000000000000001"},
149			{isNumber("1e400"), "number 1e400"},
150			{isString("1e400"), "string \"1e400\""},
151			{isBool(true), "boolean true"},
152			{isBool(false), "boolean false"},
153			{isNull(), "null"},
154		}
