169			t.Fatalf("input-owned extra members must not be hoisted next to their siblings: %#v", extra1)
170		}
171	
172		extra2 := second["extra"].(map[string]any)
173		if got, ok := extra2["asString"].(string); !ok || got != "1.0000000000000000001" {
174			t.Fatalf("a string-written number must remain a distinct string, got %#v", extra2["asString"])
175		}
176		if got, ok := extra2["huge"].(json.Number); !ok || string(got) != "1e400" {
177			t.Fatalf("top-level extra huge must be JSON number 1e400, got %#v", extra2["huge"])
