181	// A mixed batch: in-network hits interleaved with an out-of-network valid
182	// log, a blank line, and a time-invalid log whose source lies outside the
183	// selected network. The hits come out in input order with their physical
184	// line numbers and their own evidence — nothing from a dropped or failed
185	// line leaks into them — the out-of-network valid log produces no record
186	// and no failure, and the invalid line still fails with its line number, a
187	// timestamp reason and no event. Exit 1, stderr empty.
188	func TestNormalizeCLISourceCIDRMixedBatchEvidenceIsolation(t *testing.T) {
189		input := strings.Join([]string{
190			cidrEvidenceHit1, // line 1: kept
191			`{"timestamp":"2026-01-02T00:00:01Z","action":"outside","source_ip":"198.51.100.9","secret":"must-not-leak"}`, // line 2: dropped, no failure
192			`{"timestamp":"not-a-time","action":"broken","source_ip":"198.51.100.9"}`,                                     // line 3: failure despite out-of-network source
193			"",               // line 4: blank, only consumes a line number
194			cidrEvidenceHit2, // line 5: kept
195		}, "\n") + "\n"
196	
197		result := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.2.0/24")
198	
199		if result.exitCode != 1 {
200			t.Fatalf("the time-invalid line must force exit 1 even though its source is out-of-network, got %d", result.exitCode)
201		}
202		if result.stderr != "" {
203			t.Fatalf("per-line reasons belong in stdout records, not stderr, got %q", result.stderr)
204		}
205	
206		lines := rawResultLines(t, result.stdout)
207		if len(lines) != 3 {
208			t.Fatalf("expected 2 kept hits + 1 failure record, got %d: %q", len(lines), result.stdout)
209		}
210		records := decodeStdoutResultsWithNumbers(t, result.stdout)
211	
212		// Input order and physical line numbers survive filtering and failure.
213		if records[0]["line"] != json.Number("1") || records[0]["ok"] != true {
214			t.Fatalf("record 0 must be the line-1 hit: %#v", records[0])
215		}
216		if records[1]["line"] != json.Number("3") || records[1]["ok"] != false {
217			t.Fatalf("record 1 must be the line-3 failure: %#v", records[1])
218		}
219		if records[2]["line"] != json.Number("5") || records[2]["ok"] != true {
220			t.Fatalf("record 2 must be the line-5 hit: %#v", records[2])
221		}
222	
223		// The failure record: original line number, explicit timestamp reason,
224		// no event — the out-of-network source does not hide it.
225		failure := records[1]
226		if _, exists := failure["event"]; exists {
227			t.Fatalf("the time-invalid line must carry no event: %#v", failure)
228		}
229		msg, _ := failure["error"].(string)
230		if !strings.Contains(msg, `"timestamp"`) || !strings.Contains(msg, "invalid RFC3339 timestamp") {
231			t.Fatalf("the failure must name the timestamp problem, got %q", msg)
232		}
233	
234		// Each kept hit carries exactly its own evidence: the dropped line's
235		// fields and the failed line's fields appear nowhere, and the second
236		// hit's extra holds only its own four members.
237		for _, leaked := range []string{"must-not-leak", "secret", "outside", "broken"} {
238			if strings.Contains(result.stdout, leaked) {
239				t.Fatalf("dropped/failed line content %q must not appear in the output:\n%s", leaked, result.stdout)
240			}
241		}
242		requireContains(t, lines[0], cidrEvidenceHit1Extra)
243		extra2 := eventOf(t, records[2])["extra"].(map[string]any)
244		if len(extra2) != 4 {
245			t.Fatalf("the line-5 hit must carry only its own extra members, not line 1's: %#v", extra2)
246		}
247		for _, foreign := range []string{"nested", "alpha", "zeta", "extra"} {
248			if _, leaked := extra2[foreign]; leaked {
249				t.Fatalf("line 1's extra member %q must not leak into line 5's event: %#v", foreign, extra2)
250			}
251		}
252		if got := extra2["big"]; got != json.Number("9007199254740993") {
253			t.Fatalf("line 5's own evidence must survive the mixed batch, got %#v", got)
254		}
255	}
256	
257	// Filtering is selection only: the same hit logs produce byte-identical
258	// result records whether or not --source-cidr is given, and a run in which
259	// every valid log falls outside the network is a clean empty run (exit 0,
260	// empty stdout and stderr).
261	func TestNormalizeCLISourceCIDRFilteredOutputMatchesUnfiltered(t *testing.T) {
262		input := cidrEvidenceHit1 + "\n" + cidrEvidenceHit2 + "\n"
263	
264		filtered := runNormalizeCLIArgs(t, strings.NewReader(input), "--source-cidr", "192.0.2.0/24")
265		unfiltered := runNormalizeCLI(t, strings.NewReader(input))
266	
267		if filtered.exitCode != 0 || unfiltered.exitCode != 0 {
268			t.Fatalf("both runs of an all-valid batch must exit 0, got %d and %d", filtered.exitCode, unfiltered.exitCode)
269		}
270		if filtered.stdout != unfiltered.stdout {
271			t.Fatalf("kept records must be identical with and without the filter:\nfiltered:   %s\nunfiltered: %s",
272				filtered.stdout, unfiltered.stdout)
273		}
274	
275		droppedOnly := `{"timestamp":"2026-01-02T00:00:01Z","action":"outside","source_ip":"198.51.100.9","big":9007199254740993}` + "\n"
276		allDropped := runNormalizeCLIArgs(t, strings.NewReader(droppedOnly), "--source-cidr", "192.0.2.0/24")
277		if allDropped.exitCode != 0 {
278			t.Fatalf("an all-valid, fully filtered run must exit 0, got %d (stderr: %q)", allDropped.exitCode, allDropped.stderr)
279		}
280		if allDropped.stdout != "" || allDropped.stderr != "" {
281			t.Fatalf("no surviving records means empty stdout/stderr, got %q / %q", allDropped.stdout, allDropped.stderr)
282		}
283	}
